$options=getopt('',['phase:','output:']);$phase=$options['phase']??'pilot';$output=$options['output']??null;
if(!in_array($phase,['pilot','heavy-pilot','heavy-seed'],true)||!is_string($output)||!is_dir($output))throw new InvalidArgumentException('Use --phase=pilot --output=<existing directory>');
$container=Bootstrap::buildContainer();$db=$container->get(Connection::class);$p=$db->pdo();$database=(string)$p->query('SELECT DATABASE()')->fetchColumn();
if(!preg_match('/^myucto_nno_property_benchmark_[a-z0-9_]+_test$/D',$database)||!in_array($container->get(MyInvoice\Infrastructure\Config\Config::class)->get('db.host'),['localhost','127.0.0.1','::1'],true))throw new RuntimeException('Exact owned local synthetic benchmark database required');
$p->exec("SET SESSION sql_mode='STRICT_ALL_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION'");
$counts=static fn():array=>$p->query("SHOW SESSION STATUS WHERE Variable_name IN ('Com_select','Com_insert','Com_update','Com_delete','Rows_read','Rows_sent')")->fetchAll(PDO::FETCH_KEY_PAIR);
if($phase==='heavy-seed'){
    $fixture=json_decode(file_get_contents($output.'/heavy-pilot.json'),true,512,JSON_THROW_ON_ERROR);
    if($fixture['database']!==$database||$fixture['seed']['units']!==400)throw new RuntimeException('Verified heavy pilot required');$f=$fixture['fixture'];$supplier=$f['supplier'];$dataset=new PropertyBenchmarkDataset($db,$container);
    $freeze=[];foreach([MyInvoice\Repository\Property\Charges\Issuance\IssuanceRepository::class,MyInvoice\Service\Property\Charges\Issuance\IssuanceUseGuard::class,MyInvoice\Service\Property\Charges\Issuance\IssuanceLocks::class,MyInvoice\Repository\Property\PropertyReadRepository::class,MyInvoice\Service\Accounting\PostingService::class] as $class){$file=(new ReflectionClass($class))->getFileName();$freeze[$class]=['file'=>$file,'sha256'=>hash_file('sha256',$file)];}
    $done=[];$p->beginTransaction();try{$q=$p->prepare('SELECT id FROM unit_charge_batches WHERE supplier_id=? ORDER BY id FOR UPDATE');$q->execute([$supplier]);foreach($q->fetchAll(PDO::FETCH_COLUMN) as $id){$batch=(new MyInvoice\Repository\Property\Charges\Issuance\IssuanceReadRepository($db))->batch($supplier,(int)$id,true);$month=substr($batch['request']['period_from'],0,7);if($batch['request']['source_key']!=='BENCH-MONTH-'.$month||count($batch['charges'])!==400||array_unique(array_column($batch['charges'],'status'))!==['posted'])throw new RuntimeException('Existing heavy native batch incomplete');(new MyInvoice\Service\Property\Charges\Issuance\IssuanceJournalProof($db))->assertEntries($supplier,array_map(static fn($charge)=>['entry_id'=>$charge['journal_entry_id'],'charge'=>$charge,'reversal'=>false],$batch['charges']));$done[$month]=(int)$id;}$p->commit();}catch(Throwable $e){if($p->inTransaction())$p->rollBack();throw $e;}
    $progress=['schema'=>1,'database'=>$database,'supplier_id'=>$supplier,'units'=>400,'planned_months'=>120,'source_types'=>['native_monthly_charge_issuance'],'bootstrap_root'=>Bootstrap::rootDir(),'freeze'=>$freeze,'verified_existing'=>$done,'new_months'=>[]];
