    foreach(new DatePeriod(new DateTimeImmutable('2016-01-01'),new DateInterval('P1M'),new DateTimeImmutable('2026-01-01')) as $date){$month=$date->format('Y-m');if(isset($done[$month]))continue;foreach($freeze as $proof)if(!hash_equals($proof['sha256'],hash_file('sha256',$proof['file'])))throw new RuntimeException('Frozen native benchmark code changed');$before=$counts();$row=$dataset->issueMonth($f,$month);$after=$counts();$row['sql_delta']=[];foreach($after as $key=>$value)$row['sql_delta'][$key]=(int)$value-(int)$before[$key];$row['within_30s']=$row['total_ms']<=30000;$bad=$bad||!$row['within_30s'];$row['peak_bytes']=memory_get_peak_usage(true);$progress['new_months'][]=$row;file_put_contents($output.'/heavy-seed-progress.json',json_encode($progress,JSON_THROW_ON_ERROR|JSON_PRETTY_PRINT));echo json_encode($row,JSON_THROW_ON_ERROR).PHP_EOL;fflush(STDOUT);}
    $q=$p->prepare("SELECT COUNT(*) FROM unit_charges WHERE supplier_id=? AND status='posted'");$q->execute([$supplier]);$charges=(int)$q->fetchColumn();if($charges!==48000)throw new RuntimeException('Heavy native charge count must be48000');$progress['complete']=true;$progress['charges']=$charges;$progress['timing_acceptance_during_seed']=!$bad;file_put_contents($output.'/heavy-seed-progress.json',json_encode($progress,JSON_THROW_ON_ERROR|JSON_PRETTY_PRINT));echo json_encode(['complete'=>true,'charges'=>$charges,'timing_acceptance_during_seed'=>!$bad],JSON_THROW_ON_ERROR).PHP_EOL;exit($bad?2:0);
