$unitCount=$phase==='pilot'?12:400;$monthList=$phase==='pilot'?['2016-01','2016-02']:['2016-01'];
$dataset=new PropertyBenchmarkDataset($db,$container);$started=hrtime(true);$f=$dataset->create($unitCount,'2016-01-01',$phase);$catalogMs=(hrtime(true)-$started)/1e6;
