$known=(new DateTimeImmutable('now',new DateTimeZone('UTC')))->format('Y-m-d\TH:i:s.u\Z');$asOf='2026-12-31T23:59:59+01:00';$before=$counts();$started=hrtime(true);$page=(new PropertySaldoReadRepository($db))->page($f['supplier'],$asOf,$known,25);$readMs=(hrtime(true)-$started)/1e6;$after=$counts();$delta=[];foreach($after as $key=>$value)$delta[$key]=(int)$value-(int)$before[$key];
