$totals=[];foreach($page['items'] as $item){if(!$item['coverage']['financial_complete'])throw new RuntimeException('Incomplete native financial coverage');$totals[]=$item['totals']['gross_receivable_cents'];}
if(array_unique($totals)!==[(string)(180000*count($monthList))])throw new RuntimeException('Exact two-month unit receivable mismatch');
$result=['schema'=>1,'phase'=>$phase,'database'=>$database,'bootstrap_root'=>Bootstrap::rootDir(),'seed'=>['units'=>$unitCount,'months'=>count($monthList),'charges'=>$unitCount*count($monthList),'components_per_charge'=>3,'catalog_ms'=>$catalogMs],'months'=>$months,'saldo'=>['ms'=>$readMs,'units'=>count($page['items']),'delta'=>$delta,'reference_parity'=>true,'financial_complete'=>true,'digest'=>hash('sha256',json_encode($page['items'],JSON_THROW_ON_ERROR))],'fixture'=>$f];
file_put_contents($output.'/'.$phase.'.json',json_encode($result,JSON_THROW_ON_ERROR|JSON_PRETTY_PRINT));echo json_encode(array_diff_key($result,['fixture'=>true]),JSON_THROW_ON_ERROR).PHP_EOL;
